import { CATALOG_SECTIONS } from "./fixtures";
import { CatalogSection } from "./types";

export interface RawCatalogPage {
  items: CatalogSection[];
  page: number;
  pageSize: number;
  /** Total number of sections in the RAW catalog -- knows nothing about any student's schedule. */
  totalCount: number;
  /** Total pages over the RAW catalog. */
  totalPages: number;
}

/**
 * Simulates a paginated catalog/search endpoint (think: a real backend
 * search query with LIMIT/OFFSET or a cursor). This is the "index" the
 * server-side query is built on. It sorts and paginates sections, but it
 * has no idea any particular student's schedule exists -- so it cannot
 * exclude conflicting sections itself.
 */
export function getCatalogPage(pageNumber: number, pageSize: number): RawCatalogPage {
  if (pageNumber < 1) throw new Error("pageNumber must be >= 1");
  if (pageSize < 1) throw new Error("pageSize must be >= 1");

  const totalCount = CATALOG_SECTIONS.length;
  const totalPages = Math.ceil(totalCount / pageSize);
  const start = (pageNumber - 1) * pageSize;
  const items = CATALOG_SECTIONS.slice(start, start + pageSize);

  return { items, page: pageNumber, pageSize, totalCount, totalPages };
}
